import SwiftUI

struct FavoritesView:View{ @EnvironmentObject var model:AppViewModel;var body:some View{NavigationStack{List{ForEach(model.library.favorites,id:\.objectID){entry in if let item=model.library.media(from:entry.rawJSON){NavigationLink(value:item){LibraryRow(title:entry.title,poster:entry.posterURL,subtitle:entry.year)}}}.onDelete{indexes in indexes.map{model.library.favorites[$0]}.forEach{entry in if let item=model.library.media(from:entry.rawJSON){model.library.toggle(item)}}}}.scrollContentBackground(.hidden).background(Color.jiroxBackground).navigationTitle("Избранное").navigationDestination(for:MediaItem.self){DetailsView(item:$0)}}}}
struct HistoryView:View{ @EnvironmentObject var model:AppViewModel;var body:some View{NavigationStack{List(model.library.history,id:\.objectID){entry in Button{Task{await model.continueWatching(entry)}}label:{LibraryRow(title:entry.title,poster:entry.posterURL,subtitle:[entry.season.isEmpty ? nil:"Сезон \(entry.season)",entry.episode.isEmpty ? nil:"Серия \(entry.episode)"].compactMap{$0}.joined(separator:" • "),progress:entry.duration>0 ? entry.position/entry.duration:0)}}.scrollContentBackground(.hidden).background(Color.jiroxBackground).navigationTitle("История")}}}
private struct LibraryRow:View{let title:String;let poster:String;let subtitle:String;var progress:Double=0;var body:some View{HStack(spacing:14){CachedAsyncImage(url:URL(string:poster),contentMode:.fill).frame(width:62,height:88).clipped().clipShape(RoundedRectangle(cornerRadius:8));VStack(alignment:.leading){Text(title).font(.headline);Text(subtitle).font(.caption).foregroundStyle(.secondary);if progress>0{ProgressView(value:progress).tint(.red)}}}}}
